import os,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
I=G['Demo pair 1 input']; O=G['Demo pair 1 output']
import numpy as np
I=np.array(I); O=np.array(O)
print(I.shape,O.shape)
# split O into 8x10 blocks
for bi in range(3):
    for bj in range(2):
        B=O[bi*8:(bi+1)*8, bj*10:(bj+1)*10]
        match=[]
        for name,C in [('I',I),('v',I[::-1]),('h',I[:,::-1]),('hv',I[::-1,::-1]),('T',I.T),('Tv',I.T[::-1]),('Th',I.T[:,::-1]),('Thv',I.T[::-1,::-1])]:
            if C.shape==B.shape and (C==B).all(): match.append(name)
        print(bi,bj,match)

import numpy as np
O2=np.array(O)
print('vflip sym:', (O2==O2[::-1]).all())
print('hflip sym:', (O2==O2[:,::-1]).all())
print('180 sym:', (O2==O2[::-1,::-1]).all())
print('transpose sym:', O2.shape[0]==O2.shape[1] and (O2==O2.T).all())
# where does I sit inside O? find occurrences
for name,C in [('I',I),('v',I[::-1]),('h',I[:,::-1]),('hv',I[::-1,::-1])]:
    locs=[]
    for r in range(O2.shape[0]-C.shape[0]+1):
        for c in range(O2.shape[1]-C.shape[1]+1):
            if (O2[r:r+C.shape[0],c:c+C.shape[1]]==C).all(): locs.append((r,c))
    print(name, locs)
